def flatten(o):
    if o == {} or o == []:
        return {}
    out = {}
    def walk(v, prefix):
        if isinstance(v, dict):
            for k, item in v.items():
                walk(item, prefix + str(k) + '.')
        elif isinstance(v, list):
            for i, item in enumerate(v):
                walk(item, prefix + str(i) + '.')
        else:
            out[prefix[:-1]] = v
    walk(o, '')
    return out
